  type Confidence,
} from "@/data/heavy-industrial-capacity-update-202608-data";

// viz-types: diverging ?? bars, MIIT stacked triple, Clarksons orders-vs-backlog, scope ladder, steel June YoY, aircraft composed, capacity radar, dock+forge + scatter | layout: default
// viz-plan: China Clarksons H1 orders 72% CGT (+6 pp); MIIT DWT orders 82.3%; steel June share flat; docks/forges held

type Tab =
  | "deltas"
  | "miit"
  | "clarksons"
  | "scope"
  | "steel"
  | "aircraft"
  | "radar"
  | "held";
type DeltaFilter = "all" | "moved" | "held";
type SteelMode = "yoy" | "share" | "mt" | "regions";
type ClarkMode = "orders" | "backlog" | "both";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "bg-slate-100 text-slate-700 hover:bg-slate-200"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function confidenceTone(c: Confidence): string {
  if (c === "disclosed") return "text-emerald-700 bg-emerald-50";
  if (c === "derived") return "text-amber-700 bg-amber-50";
  if (c === "estimated") return "text-sky-700 bg-sky-50";
  return "text-slate-600 bg-slate-100";
}

