                  tickFormatter={(v) => `${v}%`}
                />
                <Tooltip />
                <Legend />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="duo"
                  name="Duo total"
                  fill="#e2e8f0"
                  stroke="#94a3b8"
                  fillOpacity={0.5}
                />
                <Bar
                  yAxisId="left"
                  dataKey="airbus"
                  name="Airbus"
                  fill="#3b82f6"
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  yAxisId="left"
                  dataKey="boeing"
                  name="Boeing"
                  fill="#f59e0b"
                  radius={[4, 4, 0, 0]}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="airbusSharePct"
                  name="Airbus % duo"
                  stroke="#0f172a"
                  strokeWidth={2}
                  dot={{ r: 3 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {tab === "radar" && (
        <ChartCard
          title="Capacity intensity radar ??? prior vs newest"
          subtitle="Prior = Q3 baselines; newest = Aug 202608 meters. Forge axis is shop count, not %."
        >
          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart data={radarRows} cx="50%" cy="50%" outerRadius="75%">
                <PolarGrid stroke="#e2e8f0" />
                <PolarAngleAxis dataKey="axis" tick={{ fontSize: 11 }} />
                <PolarRadiusAxis tick={{ fontSize: 10 }} />
                <Tooltip />
                <Radar
                  name="Prior (Q3)"
                  dataKey="prior"
                  stroke="#64748b"
                  fill="#94a3b8"
                  fillOpacity={0.25}
                />
                <Radar
                  name="Newest"
                  dataKey="neu"
                  stroke="#be123c"
                  fill="#fb7185"
                  fillOpacity={0.35}
                />
                <Legend />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {tab === "held" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="VLCC-capable dry docks (held)"
            subtitle="No new audited global registry since the research / Q3 maps."
          >
            <div className="h-[280px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={VLCC_DOCK_HELD}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" domain={[0, 70]} tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={72}
                    tick={{ fontSize: 12 }}
                  />
                  <Tooltip />
                  <Bar dataKey="sharePct" radius={[0, 4, 4, 0]}>
                    {VLCC_DOCK_HELD.map((d) => (
                      <Cell key={d.id} fill={d.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Ultra-heavy RPV-class forge club (held)"
            subtitle="Six shops. Still zero US members on the open-die RPV-class list."
          >
            <ul className="space-y-2">
              {FORGE_SHOPS.map((f) => (
                <li
                  key={f.id}
                  className="flex items-center justify-between rounded-lg border border-slate-100 px-3 py-2 text-sm"
                >
                  <span className="font-medium text-slate-800">
                    <span
                      className="mr-2 inline-block h-2.5 w-2.5 rounded-full"
                      style={{ backgroundColor: f.color }}
                    />
                    {f.short}
                  </span>
                  <span className="text-slate-500">
                    {f.country} ?? {f.note}
                  </span>
                </li>
              ))}
            </ul>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500">
        {SOURCES.map((s) => (
          <a
            key={s.label}
            href={s.url}
            className="underline decoration-slate-300 hover:text-slate-800"
            target="_blank"
            rel="noreferrer"
          >
            {s.label}
          </a>
        ))}
      </div>
    </div>
  );
}

