"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  PolarAngleAxis,
  PolarGrid,
  PolarRadiusAxis,
  Radar,
  RadarChart,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  AIRCRAFT_MONTHLY_2026,
  AIRCRAFT_YTD,
  CAPACITY_RADAR,
  CLARKSONS_H1_ORDERS,
  FORGE_SHOPS,
  HEADLINE,
  MIIT_TRIPLE,
  SCOPE_LADDER,
  SECTOR_LEADER_DELTAS,
  SOURCE_NOTE,
  SOURCES,
  STEEL_JUN_LEADERS,
  STEEL_REGIONS_JUN,
  VLCC_DOCK_HELD,
  VINTAGE_DELTAS,
  fmtMt,
  fmtPct,
  fmtPp,
  type Confidence,
} from "@/data/heavy-industrial-capacity-update-202608-data";

// viz-types: diverging ?? bars, MIIT stacked triple, Clarksons orders-vs-backlog, scope ladder, steel June YoY, aircraft composed, capacity radar, dock+forge + scatter | layout: default
// viz-plan: China Clarksons H1 orders 72% CGT (+6 pp); MIIT DWT orders 82.3%; steel June share flat; docks/forges held

type Tab =
  | "deltas"
  | "miit"
  | "clarksons"
  | "scope"
  | "steel"
  | "aircraft"
  | "radar"
  | "held";
type DeltaFilter = "all" | "moved" | "held";
type SteelMode = "yoy" | "share" | "mt" | "regions";
type ClarkMode = "orders" | "backlog" | "both";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-2.5 py-1 text-xs font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "bg-slate-100 text-slate-700 hover:bg-slate-200"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function confidenceTone(c: Confidence): string {
  if (c === "disclosed") return "text-emerald-700 bg-emerald-50";
  if (c === "derived") return "text-amber-700 bg-amber-50";
  if (c === "estimated") return "text-sky-700 bg-sky-50";
  return "text-slate-600 bg-slate-100";
}

export function HeavyIndustrialCapacityUpdate202608Dashboard() {
  const [tab, setTab] = useState<Tab>("deltas");
  const [deltaFilter, setDeltaFilter] = useState<DeltaFilter>("all");
  const [steelMode, setSteelMode] = useState<SteelMode>("yoy");
  const [clarkMode, setClarkMode] = useState<ClarkMode>("both");

  const deltaRows = useMemo(() => {
    return VINTAGE_DELTAS.filter((d) => {
      if (deltaFilter === "moved") return d.deltaPp !== 0;
      if (deltaFilter === "held") return d.deltaPp === 0;
      return true;
    }).map((d) => ({
      ...d,
      fill: d.deltaPp > 0 ? "#be123c" : d.deltaPp < 0 ? "#0369a1" : "#94a3b8",
    }));
  }, [deltaFilter]);

  const clarkRows = useMemo(() => {
    return CLARKSONS_H1_ORDERS.map((r) => {
      if (clarkMode === "orders") {
        return { ...r, a: r.ordersPct, b: 0, labelA: "Orders % CGT" };
      }
      if (clarkMode === "backlog") {
        return { ...r, a: r.backlogPct, b: 0, labelA: "Backlog % CGT" };
      }
      return {
        ...r,
        a: r.ordersPct,
        b: r.backlogPct,
        labelA: "Orders",
        labelB: "Backlog",
      };
    });
  }, [clarkMode]);

  const steelBars = useMemo(() => {
    type SteelBar = {
      label: string;
      value: number;
      fill: string;
      color: string;
      mt?: number;
    };
    if (steelMode === "regions") {
      return STEEL_REGIONS_JUN.map(
        (s): SteelBar => ({
          label: s.short,
          value: s.yoyPct,
          fill: s.yoyPct >= 0 ? "#be123c" : "#0369a1",
          color: s.color,
          mt: s.mtJun,
        }),
      );
    }
    return STEEL_JUN_LEADERS.map((s): SteelBar => {
      if (steelMode === "share") {
        return {
          label: s.short,
          value: s.sharePct,
          fill: s.color,
          color: s.color,
        };
      }
      if (steelMode === "mt") {
        return {
          label: s.short,
          value: s.mtJun,
          fill: s.color,
          color: s.color,
        };
      }
      return {
        label: s.short,
        value: s.yoyPct,
        fill: s.yoyPct >= 0 ? "#be123c" : "#0369a1",
        color: s.color,
      };
    });
  }, [steelMode]);

  const radarRows = useMemo(
    () =>
      CAPACITY_RADAR.map((r) => ({
        axis: r.short,
        prior: r.prior,
        neu: r.neu,
        full: r.axis,
        unit: r.unit,
      })),
    [],
  );

  const sectorCompare = useMemo(
    () =>
      SECTOR_LEADER_DELTAS.map((s) => ({
        label: s.short,
        prior: s.prior,
        neu: s.neu,
        delta: s.deltaPp,
        fill: s.color,
        status: s.status,
      })),
    [],
  );

  const scatterRows = useMemo(
    () =>
      CLARKSONS_H1_ORDERS.filter((r) => r.id !== "rest").map((r) => ({
        name: r.short,
        orders: r.ordersPct,
        backlog: r.backlogPct,
        size: Math.max(80, r.ordersCgtM * 8),
        fill: r.color,
      })),
    [],
  );

  return (
    <div
      className="space-y-6"
      data-viz="heavy-industrial-capacity-update-202608"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-5 text-white shadow-sm sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-wider text-slate-300">
          Vintage delta ?? Aug 202608
        </p>
        <p className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">
          China H1 order share {fmtPct(HEADLINE.chinaOrdersCgtPct, 0)} CGT
          <span className="ml-2 text-lg font-semibold text-rose-300">
            ({fmtPp(HEADLINE.chinaOrdersCgtDeltaPp)} vs prior GT print)
          </span>
        </p>
        <p className="mt-2 max-w-3xl text-sm text-slate-300">
          Versus the Q3 update: Clarksons H1 2026 puts China at{" "}
          {fmtPct(HEADLINE.chinaOrdersCgtPct, 0)} of global newbuild CGT (
          {fmtMt(HEADLINE.chinaOrdersCgtM, 1)}; world +
          {HEADLINE.globalOrdersCgtYoyPct}% YoY). MIIT DWT says{" "}
          {fmtPct(HEADLINE.chinaOrdersDwtPct)} of orders and{" "}
          {fmtPct(HEADLINE.chinaCompletionsDwtPct)} of completions. World Steel
          June: China {fmtMt(HEADLINE.chinaSteelJunMt)} (
          {fmtPct(HEADLINE.chinaSteelJunYoyPct, 1)} YoY) ??? share still ~
          {fmtPct(HEADLINE.chinaSteelJunSharePct)}. Docks ~{HEADLINE.vlccDockChinaPct}%
          and the {HEADLINE.ultraHeavyForgeShops}-shop forge club stay held.
        </p>
      </div>

      <div className="flex flex-wrap gap-2">
        {(
          [
            ["deltas", "Vintage ??"],
            ["miit", "MIIT triple"],
            ["clarksons", "Clarksons CGT"],
            ["scope", "Scope ladder"],
            ["steel", "Steel June"],
            ["aircraft", "Aircraft YTD"],
            ["radar", "Capacity radar"],
            ["held", "Docks & forges"],
          ] as const
        ).map(([id, label]) => (
          <button
            key={id}
            type="button"
            onClick={() => setTab(id)}
            className={`rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
              tab === id
                ? "bg-slate-900 text-white"
                : "bg-slate-100 text-slate-700 hover:bg-slate-200"
            }`}
          >
            {label}
          </button>
        ))}
      </div>

      {tab === "deltas" && (
        <div className="space-y-4">
          <ToggleGroup
            label="Show"
            value={deltaFilter}
            options={[
              { id: "all", label: "All metrics" },
              { id: "moved", label: "Moved only" },
              { id: "held", label: "Held / flat" },
            ]}
            onChange={setDeltaFilter}
          />
          <ChartCard
            title="Q3 update ??? Aug 202608 official print"
            subtitle="Diverging percentage-point change. Rose = up; blue = down; gray = held. Scope caveats in tooltips."
          >
            <div className="h-[400px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={deltaRows}
                  layout="vertical"
                  margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v > 0 ? "+" : ""}${v}`}
                    domain={["dataMin - 1", "dataMax + 1"]}
                  />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={108}
                    tick={{ fontSize: 11 }}
                  />
                  <Tooltip
                    formatter={(v, _n, p) => {
                      const row = p?.payload;
                      return [
                        `${fmtPp(Number(v))} (${row?.prior} ??? ${row?.neu} ${row?.unit})`,
                        row?.label ?? "??",
                      ];
                    }}
                  />
                  <ReferenceLine x={0} stroke="#64748b" />
                  <Bar dataKey="deltaPp" radius={[0, 4, 4, 0]}>
                    {deltaRows.map((d) => (
                      <Cell key={d.id} fill={d.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <div className="overflow-x-auto rounded-xl border border-slate-200">
            <table className="min-w-full text-left text-sm">
              <thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500">
                <tr>
                  <th className="px-3 py-2">Metric</th>
                  <th className="px-3 py-2">Prior</th>
                  <th className="px-3 py-2">New</th>
                  <th className="px-3 py-2">??</th>
                  <th className="px-3 py-2">Conf.</th>
                </tr>
              </thead>
              <tbody>
                {VINTAGE_DELTAS.map((d) => (
                  <tr key={d.id} className="border-t border-slate-100">
                    <td className="px-3 py-2 font-medium text-slate-800">
                      {d.label}
                    </td>
                    <td className="px-3 py-2 tabular-nums">{d.prior}</td>
                    <td className="px-3 py-2 tabular-nums">{d.neu}</td>
                    <td className="px-3 py-2 tabular-nums">{fmtPp(d.deltaPp)}</td>
                    <td className="px-3 py-2">
                      <span
                        className={`rounded px-1.5 py-0.5 text-xs font-medium ${confidenceTone(d.confidence)}`}
                      >
                        {d.confidence}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {tab === "miit" && (
        <ChartCard
          title="MIIT H1 2026 ??? China vs rest (DWT)"
          subtitle="Official three indicators. Orders (82.3%) run far ahead of completions (62.2%) ??? forward yard load."
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={MIIT_TRIPLE}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  domain={[0, 100]}
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v}%`}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={72}
                  tick={{ fontSize: 12 }}
                />
                <Tooltip
                  formatter={(v, name, p) => {
                    const row = p?.payload;
                    if (name === "chinaPct") {
                      return [
                        `${fmtPct(Number(v))} ?? ${fmtMt(row?.chinaMt ?? 0)} ?? YoY ${fmtPct(row?.yoyPct ?? 0, 1)}`,
                        "China",
                      ];
                    }
                    return [fmtPct(Number(v)), "Rest of world"];
                  }}
                />
                <Legend />
                <Bar
                  dataKey="chinaPct"
                  name="China"
                  stackId="a"
                  fill="#ef4444"
                  radius={[0, 0, 0, 0]}
                />
                <Bar
                  dataKey="restPct"
                  name="Rest"
                  stackId="a"
                  fill="#cbd5e1"
                  radius={[0, 4, 4, 0]}
                />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {tab === "clarksons" && (
        <div className="space-y-4">
          <ToggleGroup
            label="Metric"
            value={clarkMode}
            options={[
              { id: "both", label: "Orders + backlog" },
              { id: "orders", label: "Orders only" },
              { id: "backlog", label: "Backlog only" },
            ]}
            onChange={setClarkMode}
          />
          <div className="grid gap-4 lg:grid-cols-2">
            <ChartCard
              title="Clarksons H1 2026 CGT shares"
              subtitle="Complexity-weighted tonnage. China 72% of orders; Korea holds ~19% on both meters."
            >
              <div className="h-[320px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={clarkRows}
                    margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="short" tick={{ fontSize: 12 }} />
                    <YAxis
                      tick={{ fontSize: 11 }}
                      tickFormatter={(v) => `${v}%`}
                    />
                    <Tooltip />
                    <Legend />
                    <Bar dataKey="a" name={clarkMode === "backlog" ? "Backlog" : "Orders"} fill="#ef4444" radius={[4, 4, 0, 0]}>
                      {clarkRows.map((r) => (
                        <Cell key={r.id} fill={r.color} />
                      ))}
                    </Bar>
                    {clarkMode === "both" && (
                      <Bar
                        dataKey="b"
                        name="Backlog"
                        fill="#64748b"
                        radius={[4, 4, 0, 0]}
                      />
                    )}
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
            <ChartCard
              title="Orders ?? backlog scatter"
              subtitle="Bubble size ??? H1 order CGT. China sits upper-right; Korea balanced at ~19/19."
            >
              <div className="h-[320px] w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ScatterChart margin={{ top: 12, right: 16, left: 0, bottom: 8 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      dataKey="orders"
                      name="Orders %"
                      unit="%"
                      domain={[0, 80]}
                      tick={{ fontSize: 11 }}
                      label={{
                        value: "Orders % CGT",
                        position: "insideBottom",
                        offset: -2,
                        fontSize: 11,
                      }}
                    />
                    <YAxis
                      type="number"
                      dataKey="backlog"
                      name="Backlog %"
                      unit="%"
                      domain={[0, 80]}
                      tick={{ fontSize: 11 }}
                      label={{
                        value: "Backlog %",
                        angle: -90,
                        position: "insideLeft",
                        fontSize: 11,
                      }}
                    />
                    <ZAxis type="number" dataKey="size" range={[80, 400]} />
                    <Tooltip
                      cursor={{ strokeDasharray: "3 3" }}
                      formatter={(v, name) => [
                        typeof v === "number" ? v.toFixed(1) : v,
                        name,
                      ]}
                    />
                    <Scatter data={scatterRows}>
                      {scatterRows.map((r) => (
                        <Cell key={r.name} fill={r.fill} />
                      ))}
                    </Scatter>
                  </ScatterChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      )}

      {tab === "scope" && (
        <ChartCard
          title="Same question, four meters"
          subtitle="China yard share depends on tonnage unit. Do not average GT, CGT, and DWT."
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={SCOPE_LADDER}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  domain={[0, 90]}
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v}%`}
                />
                <YAxis
                  type="category"
                  dataKey="short"
                  width={88}
                  tick={{ fontSize: 12 }}
                />
                <Tooltip
                  formatter={(v, _n, p) => {
                    const row = p?.payload;
                    return [
                      `${fmtPct(Number(v))} (${row?.metric})${row?.deltaPp != null ? ` ?? ?? ${fmtPp(row.deltaPp)}` : ""}`,
                      row?.label,
                    ];
                  }}
                />
                <Bar dataKey="chinaPct" radius={[0, 4, 4, 0]}>
                  {SCOPE_LADDER.map((r) => (
                    <Cell key={r.id} fill={r.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 grid gap-2 sm:grid-cols-2">
            {sectorCompare.map((s) => (
              <div
                key={s.label}
                className="flex items-center justify-between rounded-lg border border-slate-100 bg-slate-50 px-3 py-2 text-sm"
              >
                <span className="font-medium text-slate-800">{s.label}</span>
                <span className="tabular-nums text-slate-600">
                  {s.prior} ??? {s.neu}{" "}
                  <span
                    className={
                      s.delta > 0
                        ? "text-rose-700"
                        : s.delta < 0
                          ? "text-sky-700"
                          : "text-slate-500"
                    }
                  >
                    ({fmtPp(s.delta)})
                  </span>
                </span>
              </div>
            ))}
          </div>
        </ChartCard>
      )}

      {tab === "steel" && (
        <div className="space-y-4">
          <ToggleGroup
            label="View"
            value={steelMode}
            options={[
              { id: "yoy", label: "YoY %" },
              { id: "share", label: "Pool share" },
              { id: "mt", label: "Mt" },
              { id: "regions", label: "Regions YoY" },
            ]}
            onChange={setSteelMode}
          />
          <ChartCard
            title="World Steel June 2026 ??? monthly print"
            subtitle="China YoY flipped positive (+0.4%) after H1 ???3%. Share still ~53.8% of the 70-country pool."
          >
            <div className="h-[380px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={steelBars}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} interval={0} angle={-25} textAnchor="end" height={60} />
                  <YAxis tick={{ fontSize: 11 }} />
                  <Tooltip />
                  {(steelMode === "yoy" || steelMode === "regions") && (
                    <ReferenceLine y={0} stroke="#64748b" />
                  )}
                  <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                    {steelBars.map((s) => (
                      <Cell key={s.label} fill={s.fill} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {tab === "aircraft" && (
        <ChartCard
          title="Airbus???Boeing monthly deliveries 2026"
          subtitle={`YTD July still ${AIRCRAFT_YTD.airbus}/${AIRCRAFT_YTD.duo} = ${fmtPct(AIRCRAFT_YTD.airbusSharePct)} Airbus. July month mix ${fmtPct(HEADLINE.airbusDuoJulMonthPct)}.`}
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={AIRCRAFT_MONTHLY_2026}
                margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="short" tick={{ fontSize: 12 }} />
                <YAxis
                  yAxisId="left"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "Deliveries",
                    angle: -90,
                    position: "insideLeft",
                    fontSize: 11,
                  }}
                />
                <YAxis
                  yAxisId="right"
                  orientation="right"
                  domain={[40, 65]}
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v}%`}
                />
                <Tooltip />
                <Legend />
                <Area
                  yAxisId="left"
                  type="monotone"
                  dataKey="duo"
                  name="Duo total"
                  fill="#e2e8f0"
                  stroke="#94a3b8"
                  fillOpacity={0.5}
                />
                <Bar
                  yAxisId="left"
                  dataKey="airbus"
                  name="Airbus"
                  fill="#3b82f6"
                  radius={[4, 4, 0, 0]}
                />
                <Bar
                  yAxisId="left"
                  dataKey="boeing"
                  name="Boeing"
                  fill="#f59e0b"
                  radius={[4, 4, 0, 0]}
                />
                <Line
                  yAxisId="right"
                  type="monotone"
                  dataKey="airbusSharePct"
                  name="Airbus % duo"
                  stroke="#0f172a"
                  strokeWidth={2}
                  dot={{ r: 3 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {tab === "radar" && (
        <ChartCard
          title="Capacity intensity radar ??? prior vs newest"
          subtitle="Prior = Q3 baselines; newest = Aug 202608 meters. Forge axis is shop count, not %."
        >
          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <RadarChart data={radarRows} cx="50%" cy="50%" outerRadius="75%">
                <PolarGrid stroke="#e2e8f0" />
                <PolarAngleAxis dataKey="axis" tick={{ fontSize: 11 }} />
                <PolarRadiusAxis tick={{ fontSize: 10 }} />
                <Tooltip />
                <Radar
                  name="Prior (Q3)"
                  dataKey="prior"
                  stroke="#64748b"
                  fill="#94a3b8"
                  fillOpacity={0.25}
                />
                <Radar
                  name="Newest"
                  dataKey="neu"
                  stroke="#be123c"
                  fill="#fb7185"
                  fillOpacity={0.35}
                />
                <Legend />
              </RadarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {tab === "held" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="VLCC-capable dry docks (held)"
            subtitle="No new audited global registry since the research / Q3 maps."
          >
            <div className="h-[280px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={VLCC_DOCK_HELD}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" domain={[0, 70]} tick={{ fontSize: 11 }} />
                  <YAxis
                    type="category"
                    dataKey="short"
                    width={72}
                    tick={{ fontSize: 12 }}
                  />
                  <Tooltip />
                  <Bar dataKey="sharePct" radius={[0, 4, 4, 0]}>
                    {VLCC_DOCK_HELD.map((d) => (
                      <Cell key={d.id} fill={d.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Ultra-heavy RPV-class forge club (held)"
            subtitle="Six shops. Still zero US members on the open-die RPV-class list."
          >
            <ul className="space-y-2">
              {FORGE_SHOPS.map((f) => (
                <li
                  key={f.id}
                  className="flex items-center justify-between rounded-lg border border-slate-100 px-3 py-2 text-sm"
                >
                  <span className="font-medium text-slate-800">
                    <span
                      className="mr-2 inline-block h-2.5 w-2.5 rounded-full"
                      style={{ backgroundColor: f.color }}
                    />
                    {f.short}
                  </span>
                  <span className="text-slate-500">
                    {f.country} ?? {f.note}
                  </span>
                </li>
              ))}
            </ul>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500">
        {SOURCES.map((s) => (
          <a
            key={s.label}
            href={s.url}
            className="underline decoration-slate-300 hover:text-slate-800"
            target="_blank"
            rel="noreferrer"
          >
            {s.label}
          </a>
        ))}
      </div>
    </div>
  );
}
